export function paginate<T>(items: T[], page: number, pageSize: number) {
  // page is 1-indexed, so convert to 0-indexed start
  const start = (page - 1) * pageSize
  const end = start + pageSize
  const pageItems = items.slice(start, end)
  const totalPages = Math.ceil(items.length / pageSize)
  return { items: pageItems, page, totalPages, hasNext: page < totalPages, hasPrev: page > 1 }
}

export function createStore<T extends { id: string }>(initial: T[] = []) {
  const items = [...initial]
  return {
    items,
    add(item: T) {
      // Immutable: return a new store with the item appended
      return createStore([...items, item])
    },
    remove(id: string) {
      // Immutable: return a new store without the removed item
      return createStore(items.filter(i => i.id !== id))
    },
    getAll() {
      // Return a copy so callers can't mutate internal state
      return [...items]
    }
  }
}

import { paginate } from "./pagination"
import { createStore } from "./store"

const items = Array.from({ length: 10 }, (_, i) => ({ id: String(i), value: i }))
const page1 = paginate(items, 1, 3) // Should return first page (indices 0-2)
console.log("Page 1 items:", page1.items)
console.log("Page 1 hasPrev:", page1.hasPrev, "hasNext:", page1.hasNext)

const store = createStore(items)
const store2 = store.add({ id: "99", value: 99 })
console.log("Original:", store.getAll().length, "New:", store2.getAll().length)

const store3 = store2.remove("0")
console.log("After remove - Original:", store2.getAll().length, "New:", store3.getAll().length)
console.log("Store 3 ids:", store3.getAll().map(i => i.id).join(","))
